SELECT /* LGUTLC00310.retrieveRequestRList */ larn.request_no AS submission_no ,larn.request_master_id AS request_master_id ,larn.request_code AS request_code ,larn.organization_id AS org_id ,lcv.short_code AS ou_short_name ,lc_approval.code_data2_value AS req_type ,lc_sys.code_data1_value AS system_code ,lc_mod.common_code_desc AS module_code ,larn.request_title AS title ,TO_CHAR(larn.request_date, 'yyyy-mm-dd hh24:mi') AS request_date ,larn.requestor_id AS requestor_id ,lumv.user_name AS approver_emp_no ,lumv.full_name_local|| '/' ||NVL(lumv.position_name,lumv.title_name) || '/' || lumv.organization_name_eng AS approver_emp_name ,lumv.english_full_name AS approver_name_eng ,larn.status_code AS status_code ,lccc.common_code_desc AS status_name FROM lgcom_approval_request_n larn ,lgcom_approval_status_n lasn ,lgcom_company_v lcv ,lgcom_user_m_v lumv ,lgcom_common_code_c lccc ,lgcom_common_code_c lc_sys ,lgcom_common_code_c lc_mod ,lgcom_common_code_c lc_approval WHERE 1 = 1 AND larn.system_code = lc_sys.common_code AND lc_sys.code_type_code = 'LGCOM_SYSTEM_CODE' AND larn.module_code = lc_mod.common_code AND larn.system_code = lc_mod.parent_common_code AND lc_mod.code_type_code = 'LGCOM_MODULE_CODE' AND larn.organization_id = lcv.organization_id AND larn.request_master_id = lasn.request_master_id AND larn.organization_id = lasn.organization_id AND larn.request_code = lasn.request_code AND lc_approval.code_type_code = 'LGCOM_APPROVAL_ACTION_CODE' AND lc_approval.common_code = lasn.approval_action_code AND larn.status_code IN ('20', '30') AND lasn.approval_action_code IN ('APPROVAL', 'AGREEMENT', 'PARAGREE_ALL', 'PARAGREE_OR') AND larn.request_date BETWEEN TO_DATE(#{dateFrom}, 'YYYY-MM-DD') AND TO_DATE(#{dateTo}, 'YYYY-MM-DD') + 1 AND lasn.sign_user_no IS NULL AND lasn.approval_date IS NULL AND lasn.approval_status_code = '2' AND lasn.user_no = lumv.user_name AND lccc.code_type_code = 'LGCOM_APPROVAL_REQ_STATUS_CODE' AND larn.status_code = lccc.common_code AND larn.requestor_id = #{USER_SESSION.applicationUserId}
AND LASN.USER_NO = #{approverEmpNo}
AND LARN.REQUEST_TITLE LIKE #{title} || '%'
ORDER BY LARN.REQUEST_DATE DESC, LARN.LAST_UPDATE_DATE DESC

